import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }

const Lipstick = ({ accent, base, style }: { accent: string; base: string; style?: React.CSSProperties }) => (
  <svg viewBox="0 0 100 100" style={style}>
    <rect x="35" y="40" width="30" height="40" fill={base} rx="5" />
    <rect x="40" y="20" width="20" height="20" fill={accent} />
    <path d="M40 20 C 40 10, 50 5, 60 20 Z" fill={accent} />
    <rect x="30" y="80" width="40" height="15" fill={base} rx="2" />
  </svg>
);

const Compact = ({ accent, base, style }: { accent: string; base: string; style?: React.CSSProperties }) => (
  <svg viewBox="0 0 100 100" style={style}>
    <circle cx="50" cy="50" r="45" fill={base} />
    <circle cx="50" cy="50" r="35" fill={accent} />
    <path d="M30 30 Q 50 10 70 30" stroke="#FFF" strokeWidth="4" fill="none" opacity={0.3} strokeLinecap="round" />
  </svg>
);

const Polish = ({ accent, base, style }: { accent: string; base: string; style?: React.CSSProperties }) => (
  <svg viewBox="0 0 100 100" style={style}>
    <rect x="25" y="45" width="50" height="50" fill={accent} rx="15" />
    <rect x="35" y="5" width="30" height="40" fill={base} rx="3" />
    <rect x="30" y="40" width="40" height="12" fill={base} rx="2" />
    <path d="M35 55 L 35 85" stroke="#FFF" strokeWidth="4" strokeLinecap="round" opacity={0.4} />
  </svg>
);

const Brush = ({ accent, base, style }: { accent: string; base: string; style?: React.CSSProperties }) => (
  <svg viewBox="0 0 100 100" style={style}>
    <path d="M30 40 Q 50 0 70 40 Z" fill={accent} />
    <rect x="35" y="40" width="30" height="15" fill="#cfd8dc" rx="2" />
    <rect x="40" y="55" width="20" height="40" fill={base} rx="5" />
  </svg>
);



export type ProductLaunchTeaserProps = Record<string, any>;

const ProductLaunchTeaser: React.FC<ProductLaunchTeaserProps> = ({
  backgroundColor = "#FDFBF7",
  transparentBackground = false,
  durationInSeconds = 5,
  gradientEndColor = "#EAE6DF",
  headline = "THE ESSENTIALS COLLECTION",
  headlineColor = "#111111",
  elementsColor = "#E91E63",
  buttonText = "Shop Now",
  buttonBgColor = "#111111",
  buttonTextColor = "#FFFFFF",
  headlineScaleMultiplier = 1.0,
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Montserrat"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgStart = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const bgEnd = transparentBackground ? `${gradientEndColor}00` : gradientEndColor;

  // Animation Timings
  const headlineEntryStart = 15;
  const buttonEntryStart = 35;

  // Headline Animations
  const headlineOpacity = interpolate(
    frame,
    [headlineEntryStart, headlineEntryStart + 30],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const headlineDrift = interpolate(
    frame,
    [headlineEntryStart, headlineEntryStart + 60],
    [height * 0.02, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const headlineScale = interpolate(
    frame,
    [headlineEntryStart, headlineEntryStart + 60],
    [0.97, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Beauty Elements Animations
  const elementScale = spring({
    frame: frame - headlineEntryStart - 15,
    fps,
    config: { damping: 12, stiffness: 120 },
  });

  const elementOpacity = interpolate(
    frame,
    [headlineEntryStart + 15, headlineEntryStart + 25],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const float1 = Math.sin(frame / 15) * (height * 0.01);
  const float2 = Math.cos(frame / 15) * (height * 0.01);

  // Button Animations
  const buttonSpring = spring({
    frame: frame - buttonEntryStart,
    fps,
    config: { damping: 14, stiffness: 100, mass: 0.8 },
  });

  const buttonTranslateY = interpolate(
    buttonSpring,
    [0, 1],
    [height * 0.1, 0]
  );

  const buttonOpacity = interpolate(
    frame,
    [buttonEntryStart, buttonEntryStart + 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Responsive Layout Calculations
  const baseFontSize = width * 0.12 * headlineScaleMultiplier;

  return (
    <AbsoluteFill
      style={{
        background: transparentBackground ? "transparent" : `linear-gradient(135deg, ${bgStart}, ${bgEnd})`,
        fontFamily: "Montserrat",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        padding: `${height * 0.15}px ${width * 0.08}px ${height * 0.1}px`, // Respecting Safe Zones
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          flex: 1,
          width: "100%",
          gap: `${height * 0.06}px`,
          transition: "none",
        }}
      >
        <div
          style={{
            position: "relative",
            width: "100%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            opacity: headlineOpacity,
            transform: `translateY(${headlineDrift}px) scale(${headlineScale})`,
            transition: "none",
          }}
        >
          <Lipstick
            accent={elementsColor}
            base={headlineColor}
            style={{
              position: "absolute",
              top: -height * 0.06,
              left: 0,
              width: width * 0.15,
              height: width * 0.15,
              transform: `scale(${elementScale}) rotate(-15deg) translateY(${float1}px)`,
              opacity: elementOpacity,
              zIndex: -1,
            }}
          />
          <Compact
            accent={elementsColor}
            base={headlineColor}
            style={{
              position: "absolute",
              bottom: height * 0.02,
              right: 0,
              width: width * 0.18,
              height: width * 0.18,
              transform: `scale(${elementScale}) rotate(25deg) translateY(${float2}px)`,
              opacity: elementOpacity,
              zIndex: -1,
            }}
          />
          <Polish
            accent={elementsColor}
            base={headlineColor}
            style={{
              position: "absolute",
              top: -height * 0.03,
              right: width * 0.05,
              width: width * 0.12,
              height: width * 0.12,
              transform: `scale(${elementScale}) rotate(15deg) translateY(${float2}px)`,
              opacity: elementOpacity,
              zIndex: -1,
            }}
          />
          <Brush
            accent={elementsColor}
            base={headlineColor}
            style={{
              position: "absolute",
              bottom: -height * 0.08,
              left: width * 0.05,
              width: width * 0.16,
              height: width * 0.16,
              transform: `scale(${elementScale}) rotate(-25deg) translateY(${float1}px)`,
              opacity: elementOpacity,
              zIndex: -1,
            }}
          />
          <h1
            style={{
              color: headlineColor,
              fontSize: `${baseFontSize}px`,
              fontWeight: 800,
              lineHeight: 1.1,
              textAlign: "center",
              margin: 0,
              textTransform: "uppercase",
              letterSpacing: "-0.02em",
              transition: "none",
            }}
          >
            {headline}
          </h1>
        </div>

        <div
          style={{
            opacity: buttonOpacity,
            transform: `translateY(${buttonTranslateY}px)`,
            backgroundColor: buttonBgColor,
            color: buttonTextColor,
            padding: `${height * 0.025}px ${width * 0.12}px`,
            borderRadius: `${height * 0.1}px`,
            fontSize: `${width * 0.045}px`,
            fontWeight: 600,
            textTransform: "uppercase",
            letterSpacing: "0.05em",
            boxShadow: "0 10px 30px rgba(0,0,0,0.1)",
            transition: "none",
          }}
        >
          {buttonText}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ProductLaunchTeaser;